require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';$id=(int)($_GET['edit']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='toggle'&&$id){$pdo->prepare('UPDATE dentists SET is_active=1-is_active WHERE id=?')->execute([$id]);audit($pdo,'dentist.availability_toggled','dentist',$id);flash('success','Dentist availability updated.');redirect('dentists.php');}$first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$phone=post_string('phone',30);$special=post_string('specialization',120);$license=post_string('license_number',80);$errors=[];if($first===''||$last===''||$license==='')$errors[]='Name and license number are required.';if($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!$errors){try{if($id){$q=$pdo->prepare('UPDATE dentists SET first_name=?,last_name=?,email=?,phone=?,specialization=?,license_number=? WHERE id=?');$q->execute([$first,$last,$email?:null,$phone?:null,$special?:null,$license,$id]);}else{$q=$pdo->prepare('INSERT INTO dentists(first_name,last_name,email,phone,specialization,license_number) VALUES(?,?,?,?,?,?)');$q->execute([$first,$last,$email?:null,$phone?:null,$special?:null,$license]);$id=(int)$pdo->lastInsertId();}audit($pdo,'dentist.saved','dentist',$id);flash('success','Dentist saved.');redirect('dentists.php');}catch(PDOException $e){$errors[]='Email or license number already exists.';}}}
$edit=$id?$pdo->prepare('SELECT * FROM dentists WHERE id=?'):null;if($edit){$edit->execute([$id]);$edit=$edit->fetch();}$dentists=$pdo->query('SELECT d.*,(SELECT COUNT(*) FROM dentist_schedules s WHERE s.dentist_id=d.id AND s.is_active=1) schedules FROM dentists d ORDER BY d.last_name')->fetchAll();page_header('Dentist Management','dentists');
?><?php if(!empty($errors)):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif?><div class="grid panels"><section class="card"><h2>Registered dentists</h2><div class="table-wrap"><table><thead><tr><th>Dentist</th><th>Specialization</th><th>Schedules</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($dentists as $d):?><tr><td><strong>Dr. <?=e($d['first_name'].' '.$d['last_name'])?></strong><br><small><?=e($d['license_number'])?></small></td><td><?=e($d['specialization']?:'General Dentistry')?></td><td><?=$d['schedules']?></td><td><span class="badge <?=$d['is_active']?'approved':'cancelled'?>"><?=$d['is_active']?'Active':'Inactive'?></span></td><td class="actions"><a class="btn secondary sm" href="?edit=<?=$d['id']?>">Edit</a><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$d['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn secondary sm"><?=$d['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?><?php if(!$dentists):?><tr><td colspan="5" class="empty">No dentists registered.</td></tr><?php endif?></tbody></table></div></section><section class="card"><h2><?=$edit?'Edit dentist':'Add dentist'?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><label>First name<input name="first_name" required value="<?=e($edit['first_name']??'')?>"></label><label>Last name<input name="last_name" required value="<?=e($edit['last_name']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>Specialization<input name="specialization" value="<?=e($edit['specialization']??'')?>"></label><label>License number<input name="license_number" required value="<?=e($edit['license_number']??'')?>"></label><div class="full"><button>Save dentist</button> <a class="btn secondary" href="schedules.php">Manage schedules</a></div></form></section></div><?php page_footer();
